/// The `lvl req` of uniqueitems row `row` (`ItemData` `FILE_INDEX`), `None` if unknown.
/// Only meaningful for an identified item: the index is filled once identified
/// (see `item_data::FILE_INDEX`).
#[must_use]
pub fn unique_level(row: u32) -> Option<u32> {
    UNIQUE_LEVELS
        .binary_search_by_key(&row, |&(i, _)| i)
        .ok()
        .and_then(|i| UNIQUE_LEVELS.get(i))
        .map(|&(_, lvl)| lvl)
}

/// The `lvl req` of setitems row `row` (`ItemData` `FILE_INDEX`), `None` if unknown.
/// Only meaningful for an identified item: the index is filled once identified
/// (see `item_data::FILE_INDEX`).
#[must_use]
pub fn set_level(row: u32) -> Option<u32> {
    SET_LEVELS
        .binary_search_by_key(&row, |&(i, _)| i)
        .ok()
        .and_then(|i| SET_LEVELS.get(i))
        .map(|&(_, lvl)| lvl)
}

/// The `levelreq` of the armor.txt row with item code `code`, `None` if unknown.
#[must_use]
pub fn armor_level(code: &str) -> Option<u32> {
    ARMOR
        .binary_search_by_key(&code, |&(c, _, _)| c)
        .ok()
        .and_then(|i| ARMOR.get(i))
        .map(|&(_, lvl, _)| lvl)
}

/// The armor.txt display name of item code `code`, `None` if unknown.
#[must_use]
pub fn armor_name(code: &str) -> Option<&'static str> {
    ARMOR
        .binary_search_by_key(&code, |&(c, _, _)| c)
        .ok()
        .and_then(|i| ARMOR.get(i))
        .map(|&(_, _, name)| name)
}

/// The quality level of uniqueitems row `row`, `None` if unknown.
#[must_use]
pub fn unique_qlvl(row: u32) -> Option<u32> {
    UNIQUE_QLVLS
        .binary_search_by_key(&row, |&(i, _)| i)
        .ok()
        .and_then(|i| UNIQUE_QLVLS.get(i))
        .map(|&(_, lvl)| lvl)
}

/// The quality level of setitems row `row`, `None` if unknown.
#[must_use]
pub fn set_qlvl(row: u32) -> Option<u32> {
    SET_QLVLS
        .binary_search_by_key(&row, |&(i, _)| i)
        .ok()
        .and_then(|i| SET_QLVLS.get(i))
        .map(|&(_, lvl)| lvl)
}

/// The quality level of rune `name` (`"Tal"` or `"Tal Rune"`, any case), `None` if unknown.
#[must_use]
pub fn rune_qlvl(name: &str) -> Option<u32> {
    let name = name.trim();
    let bare = name
        .strip_suffix(" Rune")
        .or_else(|| name.strip_suffix(" rune"))
        .unwrap_or(name);
    RUNE_QLVLS
        .iter()
        .find(|(r, _)| r.eq_ignore_ascii_case(bare))
        .map(|&(_, lvl)| lvl)
}
